"""Task and Multimodal Decomposition for Waypost v5 (Spec Section I.3).

Decomposes separable multimodal queries (e.g. OCR / description + downstream text reasoning):
1. Detects whether a multimodal request is separable or deictic/coupled.
2. Formulates sub-tasks:
   - Extraction stage: vision model transforms visual/audio into structured text.
   - Reasoning stage: text-only router evaluates the full free pool of 56 models.
"""
from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Literal

from .schemas import ChatRequest

# Deictic patterns indicate the question cannot be separated from direct visual references
DEICTIC_PATTERNS = (
    r"\bhere\b",
    r"\bthis part\b",
    r"\bcircled in\b",
    r"\bpointed at\b",
    r"\barrows?\b",
    r"\bhighlighted in\b",
    r"\bleft side of\b",
    r"\bright side of\b",
    r"\bshown here\b",
    r"\bна этом месте\b",
    r"\bобведено\b",
    r"\bстрелочк\w+\b",
    r"\bвыделенн\w+\b",
)


@dataclass
class DecomposedTask:
    is_separable: bool
    stage: Literal["single_shot", "extraction_first", "transcription_first"]
    extraction_prompt: str | None = None
    reasoning_prompt: str | None = None


def is_deictic_prompt(text: str) -> bool:
    """Check if the user prompt relies on deictic references to the image."""
    low = text.lower()
    return any(re.search(pat, low) for pat in DEICTIC_PATTERNS)


def analyze_multimodal_decomposition(req: ChatRequest) -> DecomposedTask:
    """Analyzes a request to decide if multimodal decomposition should be applied."""
    has_image = False
    has_audio = False
    user_text = ""

    for m in req.messages:
        if m.role == "user":
            if isinstance(m.content, str):
                user_text += " " + m.content
            elif isinstance(m.content, list):
                for b in m.content:
                    if isinstance(b, dict):
                        b_type = b.get("type", "")
                        if b_type in ("image_url", "image"):
                            has_image = True
                        elif b_type in ("input_audio", "audio"):
                            has_audio = True
                        elif b_type == "text":
                            user_text += " " + b.get("text", "")

    user_text = user_text.strip()

    if not has_image and not has_audio:
        return DecomposedTask(is_separable=False, stage="single_shot")

    # If deictic, keep end-to-end vision routing
    if has_image and is_deictic_prompt(user_text):
        return DecomposedTask(is_separable=False, stage="single_shot")

    if has_image:
        return DecomposedTask(
            is_separable=True,
            stage="extraction_first",
            extraction_prompt="Describe in detail all visible text, diagrams, code, and key elements from the image.",
            reasoning_prompt=user_text or "Analyze the extracted image content.",
        )

    if has_audio:
        return DecomposedTask(
            is_separable=True,
            stage="transcription_first",
            extraction_prompt="Transcribe the audio accurately.",
            reasoning_prompt=user_text or "Respond to the transcribed audio.",
        )

    return DecomposedTask(is_separable=False, stage="single_shot")


def strip_images(req: ChatRequest, extracted: str) -> ChatRequest:
    """Replace visual content with what the extraction stage read out of it.

    The image blocks are removed rather than kept alongside the text: the
    whole point is to hand the second stage to a model that has no vision
    at all, and leaving the blocks in would filter that pool right back
    out.
    """
    messages = []
    for m in req.messages:
        if not isinstance(m.content, list):
            messages.append(m)
            continue
        kept = [
            b
            for b in m.content
            if not (
                isinstance(b, dict)
                and b.get("type") in ("image_url", "image", "input_audio", "audio")
            )
        ]
        text = " ".join(
            b.get("text", "") for b in kept if isinstance(b, dict)
        ).strip()
        if m.role == "user":
            text = (
                f"{text}\n\n[Содержимое вложения, распознанное на первом шаге]\n"
                f"{extracted}"
            ).strip()
        messages.append(m.model_copy(update={"content": text}))
    return req.model_copy(update={"messages": messages})


def decomposition_gain(
    best_vision_quality: float, best_text_quality: float, margin: float = 0.12
) -> bool:
    """Is splitting worth a second call?

    Decomposition buys reasoning power and pays for it twice: an extra
    request against the quota, extra latency, and — the real cost —
    whatever the extraction stage failed to notice. A description is
    lossy in a way the original image is not.

    So it only pays when the text pool is *substantially* stronger than
    the vision pool. Where a vision model can carry the task itself,
    end-to-end is both cheaper and more faithful.
    """
    return best_text_quality - best_vision_quality >= margin


def get_vision_token_budget(task_class: str) -> int:
    """Returns the explicit vision token budget based on task type (Spec I.2).

    - classification / short caption: 70–140
    - scene description / QA: 280
    - diagrams / large text: 560
    - dense OCR / tables: 1120
    - video frames: 70
    """
    task = task_class.lower()
    if any(k in task for k in ("ocr", "table", "document", "dense")):
        return 1120
    if any(k in task for k in ("diagram", "code", "chart", "math", "schema")):
        return 560
    if any(k in task for k in ("classification", "video", "frame")):
        return 70
    return 280

"""Swarms custom-LLM adapter. No direct provider fallback is configured here."""
from __future__ import annotations

import json
import os
import threading
import time
import uuid
import httpx

from .models import SwarmConfig
from .store import RunStore


class BudgetExceeded(RuntimeError):
    pass


class RunInterrupted(RuntimeError):
    pass


class Budget:
    def __init__(self, config: SwarmConfig, state: dict, store: RunStore):
        self.config, self.state, self.store = config, state, store
        self.lock = threading.RLock()
        self.started = time.monotonic()
        self.previous_seconds = state.get("elapsed_seconds", 0)

    def remaining(self):
        if self.config.max_seconds is None:
            return float("inf")
        return self.config.max_seconds - self.previous_seconds - (time.monotonic() - self.started)

    def check(self):
        control = self.store.control()
        if control.get("interrupt"):
            raise RunInterrupted("Interrupted by user")
        if control.get("paused"):
            with self.lock:
                if self.state.get("status") != "paused":
                    self.state["status"] = "paused"
                    self.checkpoint()
                    self.store.event("paused")
            while control.get("paused"):
                time.sleep(0.2)
                control = self.store.control()
                if control.get("interrupt"):
                    raise RunInterrupted("Interrupted by user")
            with self.lock:
                self.state["status"] = "running"
                self.checkpoint()
                self.store.event("resumed")
        if self.remaining() <= 0:
            raise BudgetExceeded("Execution time budget exhausted")

    def reserve(self):
        with self.lock:
            self.check()
            if self.config.max_calls is not None and self.state["calls"] >= self.config.max_calls:
                raise BudgetExceeded("LLM call budget exhausted")
            self.state["calls"] += 1
            self.checkpoint()

    def checkpoint(self):
        with self.lock:
            self.state["elapsed_seconds"] = self.previous_seconds + time.monotonic() - self.started
            self.store.save(self.state)


class WaypostLLM:
    def __init__(self, config: SwarmConfig, budget: Budget, store: RunStore,
                 session: str, system: str, client: httpx.Client | None = None):
        self.config, self.budget, self.store = config, budget, store
        self.session, self.system, self.client = session, system, client
        self.last_response: str | None = None
        self.last_error: Exception | None = None

    def run(self, task: str | None = None, **kwargs) -> str:
        self.last_response = None
        self.last_error = None
        try:
            return self._run(task, kwargs.get("messages"))
        except Exception as exc:
            self.last_error = exc
            raise

    def _run(self, task: str | None, messages: list[dict] | None = None) -> str:
        # Swarms 15 may call custom LLMs with task=None and messages=[...].
        # Its prompt is in messages; sending None as user content fails Waypost validation.
        conversation = [{"role": "system", "content": self.system}]
        if messages:
            conversation.extend({"role": m["role"], "content": m["content"]}
                                for m in messages if m.get("role") in {"user", "assistant"}
                                and isinstance(m.get("content"), str))
        elif isinstance(task, str):
            conversation.append({"role": "user", "content": task})
        if len(conversation) == 1:
            raise ValueError("Swarms supplied no text prompt")
        self.budget.reserve()
        payload = {
            "model": self.config.model,
            "messages": conversation,
            "max_tokens": self.config.max_tokens, "temperature": 0.2,
            "response_format": {"type": "json_object"},
            "stream": False, "session_id": self.session,
            "latency_class": "batch", "no_cache": True,
            "idempotency_key": str(uuid.uuid4()),
        }
        if self.config.privacy == "strict":
            payload["privacy"] = "strict"
        timeout = min(self.config.request_timeout, self.budget.remaining())
        headers = {"Authorization": "Bearer " + os.getenv("WAYPOST_API_KEY", "unused")}
        # No implicit HTTP retries: Waypost owns upstream retry/quota accounting.
        if self.client is not None:
            response = self.client.post(self.config.base_url.rstrip("/") + "/chat/completions",
                                        json=payload, headers=headers, timeout=timeout)
        else:
            with httpx.Client(trust_env=False) as client:
                response = client.post(self.config.base_url.rstrip("/") + "/chat/completions",
                                       json=payload, headers=headers, timeout=timeout)
        response.raise_for_status()
        data = response.json()
        choices = data.get("choices")
        if not isinstance(choices, list) or not choices:
            router = data.get("router", {})
            raise ValueError(f"Waypost returned no choices (provider={router.get('provider')}, model={router.get('model')})")
        choice = choices[0]
        if choice.get("finish_reason") == "length":
            raise ValueError("Waypost response was truncated; increase max_tokens")
        content = choice["message"].get("content")
        if not isinstance(content, str) or not content.strip():
            raise ValueError("Waypost returned no text")
        self.store.event("llm_response", session=self.session,
                         router=data.get("router", {}), usage=data.get("usage", {}))
        self.last_response = content
        return content


class SwarmsBackend:
    def __init__(self, config: SwarmConfig, budget: Budget, store: RunStore):
        # Import only when the optional engine is actually run.
        os.environ["SWARMS_TELEMETRY_ON"] = "false"
        os.environ.setdefault("LITELLM_LOCAL_MODEL_COST_MAP", "True")
        try:
            from swarms import Agent
        except ModuleNotFoundError as exc:
            if exc.name == "swarms":
                raise RuntimeError("Install the optional engine: pip install -e '.[swarm]'") from exc
            raise
        self.agent_class = Agent
        self.config, self.budget, self.store = config, budget, store

    def ask(self, role: str, system: str, prompt: str) -> str:
        llm = WaypostLLM(self.config, self.budget, self.store,
                         f"{self.store.directory.name}:{role}", system)
        agent = self.agent_class(
            agent_name=role, system_prompt=system, llm=llm,
            model_name="openai/auto", max_loops=1, retry_attempts=1,
            output_type="final", autosave=False, print_on=False,
            streaming_on=False, dynamic_temperature_enabled=False,
            context_compression=False, dynamic_context_window=False,
            reasoning_prompt_on=False,
        )
        try:
            agent.run(prompt)
        except Exception:
            if llm.last_error is not None:
                raise llm.last_error
            raise
        # Read the actual adapter response, never an error string swallowed by Agent.
        if llm.last_error is not None:
            raise llm.last_error
        if llm.last_response is None:
            raise RuntimeError("Swarms did not invoke the Waypost adapter")
        return llm.last_response


def parse_json(text: str) -> dict:
    text = text.strip()
    if text.startswith("```") and text.endswith("```"):
        text = text.split("\n", 1)[1].rsplit("```", 1)[0].strip()
    result = json.loads(text)
    if not isinstance(result, dict):
        raise ValueError("Expected one JSON object")
    return result

from __future__ import annotations

from typing import Literal
from pydantic import BaseModel, ConfigDict, Field, model_validator


class StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid")


class SwarmConfig(StrictModel):
    base_url: str = "http://127.0.0.1:8080/v1"
    model: str = "auto"
    privacy: Literal["normal", "strict"] = "normal"
    concurrency: int = Field(default=2, ge=1, le=16)
    max_tasks: int | None = Field(default=None, ge=1)
    max_rounds: int | None = Field(default=None, ge=1)
    max_steps: int | None = Field(default=None, ge=1)
    max_calls: int | None = Field(default=None, ge=1)
    max_tokens: int = Field(default=4096, ge=256, le=32768)
    request_timeout: float = Field(default=310, gt=0)
    max_seconds: float | None = Field(default=None, gt=0)
    allow_python: bool = False


class Task(StrictModel):
    id: str = Field(pattern=r"^[a-zA-Z0-9_-]{1,48}$")
    role: str = Field(min_length=1, max_length=200)
    instruction: str = Field(min_length=1, max_length=12000)
    depends_on: list[str] = Field(default_factory=list)


class Plan(StrictModel):
    acceptance: list[str] = Field(min_length=1)
    tasks: list[Task] = Field(min_length=1)

    @model_validator(mode="after")
    def valid_graph(self):
        ids = {t.id for t in self.tasks}
        if ids & {"synthesis", "audit"}:
            raise ValueError("synthesis and audit are reserved task IDs")
        if len(ids) != len(self.tasks):
            raise ValueError("task IDs must be unique")
        done: set[str] = set()
        for t in self.tasks:
            if not set(t.depends_on) <= ids:
                raise ValueError(f"unknown dependencies for {t.id}")
        while len(done) < len(ids):
            ready = {t.id for t in self.tasks if t.id not in done and set(t.depends_on) <= done}
            if not ready:
                raise ValueError("dependency graph contains a cycle")
            done |= ready
        return self


class Action(StrictModel):
    kind: Literal["tool", "final"]
    tool: str | None = None
    arguments: dict = Field(default_factory=dict)
    answer: str | None = None

    @model_validator(mode="after")
    def valid_action(self):
        if self.kind == "tool" and not self.tool:
            raise ValueError("tool action requires a tool name")
        if self.kind == "final" and not (self.answer and self.answer.strip()):
            raise ValueError("final action requires a nonempty answer")
        return self


class Review(StrictModel):
    passed: bool
    findings: list[str]
    repair: Plan | None = None

    @model_validator(mode="after")
    def repair_required(self):
        if not self.passed and self.repair is None:
            raise ValueError("a failed review requires a repair plan")
        if self.passed and self.repair is not None:
            raise ValueError("a passing review must not contain a repair plan")
        return self


class ProgressDecision(StrictModel):
    action: Literal["continue", "redirect", "replan", "needs_input"]
    reason: str = Field(min_length=1)
    guidance: str = ""

"""Determining whether a model is free or costs money.

The project rule is to spend only free quotas. So the question "is this
model paid" must be settled by a mechanism, not by human memory, and
settled fail-closed: unknown → treat as paid.

Evidence is ranked by strength:

  1. BILLED     — the provider billed in the response (usage.cost > 0).
                  Strongest of all: this is a fact, not a declaration.
  2. API        — prices from GET /models (OpenRouter returns pricing.prompt;
                  some OpenAI-compatible hosts have their own fields).
  3. ID         — a ':free' / '-free' suffix in the model identifier.
  4. MANIFEST   — declared by a human in config/providers.yaml.
  5. UNKNOWN    — declared nowhere → treated as paid.

Merge: any PAID evidence overrides any FREE. An error this way costs an
unavailable model; an error the other way costs money.
"""
from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Any

# Suffixes of free variants (OpenRouter convention).
FREE_MARKERS = (":free", "-free")

# Per-token price fields in a GET /models response across hosts.
_PRICE_KEYS = (
    "prompt",
    "completion",
    "input",
    "output",
    "request",
    "image",
    "input_cost_per_token",
    "output_cost_per_token",
    "prompt_token_price",
    "completion_token_price",
    "price_per_input_token",
    "price_per_output_token",
)

# Cost fields for a request already executed (usage / usage.cost_details).
_COST_KEYS = (
    "cost",
    "total_cost",
    "cost_usd",
    "prompt_cost",
    "completion_cost",
    "upstream_inference_cost",
)


class Cost(str, Enum):
    FREE = "free"
    PAID = "paid"
    UNKNOWN = "unknown"


class Source(str, Enum):
    BILLED = "billed"  # a bill in the provider response
    API = "api"  # prices from GET /models
    ID = "id"  # a :free suffix
    MANIFEST = "manifest"  # declared in the manifest
    UNKNOWN = "unknown"  # declared nowhere


_STRENGTH = {
    Source.BILLED: 4,
    Source.API: 3,
    Source.ID: 2,
    Source.MANIFEST: 1,
    Source.UNKNOWN: 0,
}


@dataclass(frozen=True)
class Verdict:
    cost: Cost
    source: Source
    detail: str = ""

    @property
    def is_free(self) -> bool:
        """Only a provably free model is free. UNKNOWN is not free."""
        return self.cost is Cost.FREE

    def __str__(self) -> str:
        d = f" ({self.detail})" if self.detail else ""
        return f"{self.cost.value}/{self.source.value}{d}"


UNKNOWN_VERDICT = Verdict(Cost.UNKNOWN, Source.UNKNOWN, "no price data")


def _num(value: Any) -> float | None:
    """Prices arrive as strings ('0', '0.0000006') and as numbers."""
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except ValueError:
            return None
    return None


def parse_prices(model: dict[str, Any]) -> dict[str, float]:
    """All recognized prices of a model from a /models response.

    We look both in flat fields and in nested pricing/prices — the shape
    differs from host to host, the meaning is the same.
    """
    out: dict[str, float] = {}
    sources: list[dict[str, Any]] = [model]
    for nest in ("pricing", "prices", "cost", "price"):
        if isinstance(model.get(nest), dict):
            sources.append(model[nest])
    for src in sources:
        for key in _PRICE_KEYS:
            if key in src and (v := _num(src[key])) is not None:
                out[key] = v
    return out


def from_api(model: dict[str, Any]) -> Verdict:
    """Verdict from a GET /models response. UNKNOWN if it has no prices."""
    flag = model.get("free")
    if isinstance(flag, bool):
        return Verdict(
            Cost.FREE if flag else Cost.PAID, Source.API, "free field in /models"
        )

    prices = parse_prices(model)
    if not prices:
        return UNKNOWN_VERDICT

    positive = {k: v for k, v in prices.items() if v > 0}
    if positive:
        top = max(positive.items(), key=lambda kv: kv[1])
        return Verdict(Cost.PAID, Source.API, f"{top[0]}={top[1]:g}")
    # A negative price (OpenRouter sets -1 for dynamic rates) means
    # "price unknown", not "free".
    if any(v < 0 for v in prices.values()):
        return Verdict(Cost.UNKNOWN, Source.API, "dynamic rate")
    return Verdict(Cost.FREE, Source.API, "all prices = 0")


def from_model_id(model_id: str) -> Verdict:
    """A ':free' suffix is a convention, but a verifiable one: such models
    on OpenRouter always have a 0 price. No converse: the absence of the
    suffix proves nothing."""
    low = (model_id or "").lower()
    for mark in FREE_MARKERS:
        if low.endswith(mark) or f"{mark}/" in low:
            return Verdict(Cost.FREE, Source.ID, f"suffix {mark}")
    return UNKNOWN_VERDICT


def from_manifest(declared: bool | None) -> Verdict:
    """Source A. None means "not declared" — that is UNKNOWN, not free:
    this is exactly where paid models used to leak through."""
    if declared is None:
        return Verdict(Cost.UNKNOWN, Source.UNKNOWN, "free not declared in manifest")
    return Verdict(Cost.FREE if declared else Cost.PAID, Source.MANIFEST, "manifest")


def billed_cost(body: dict[str, Any]) -> float | None:
    """How much the provider charged for this answer. None if not reported.

    The last line of defense: if a bill was actually issued, the model is
    paid, whatever the manifest and /models say.
    """
    usage = body.get("usage")
    if not isinstance(usage, dict):
        return None
    total = 0.0
    found = False
    for key in _COST_KEYS:
        if (v := _num(usage.get(key))) is not None:
            total = max(total, v)
            found = True
    details = usage.get("cost_details")
    if isinstance(details, dict):
        for v in details.values():
            if (n := _num(v)) is not None:
                total = max(total, n)
                found = True
    return total if found else None


def merge(*verdicts: Verdict) -> Verdict:
    """Merge evidence. PAID takes priority over FREE from any source — a
    fail-closed policy; on a tie, the strongest source wins.
    """
    real = [v for v in verdicts if v.cost is not Cost.UNKNOWN]
    if not real:
        strongest = max(
            verdicts, key=lambda v: _STRENGTH[v.source], default=UNKNOWN_VERDICT
        )
        return strongest if verdicts else UNKNOWN_VERDICT
    paid = [v for v in real if v.cost is Cost.PAID]
    pool = paid or real
    return max(pool, key=lambda v: _STRENGTH[v.source])


def classify(
    model_id: str,
    *,
    api_model: dict[str, Any] | None = None,
    declared: bool | None = None,
    billed: float | None = None,
) -> Verdict:
    """Single entry point: gather all available evidence into one verdict."""
    verdicts = [from_manifest(declared), from_model_id(model_id)]
    if api_model is not None:
        verdicts.append(from_api(api_model))
    if billed is not None:
        verdicts.append(
            Verdict(
                Cost.PAID if billed > 0 else Cost.FREE,
                Source.BILLED,
                f"billed {billed:g}",
            )
        )
    return merge(*verdicts)


# Commercial market baseline prices in USD per 1M tokens (input, output).
# Used to calculate real money saved when routing to free tiers and local models.
# - S: GPT-4o-mini / Claude 3.5 Haiku baseline
# - M: Claude 3.5 Sonnet / GPT-4o baseline
# - L: OpenAI o1 / Claude 3.7 Thinking baseline
BASELINE_PRICING_PER_1M: dict[str, tuple[float, float]] = {
    "S": (0.15, 0.60),
    "M": (3.00, 15.00),
    "L": (15.00, 60.00),
}
BASELINE_NAME = "Waypost commercial baseline v1"


def baseline_cost(prompt_tokens: int, completion_tokens: int, tier: str = "M") -> float:
    """Estimated commercial cost in USD for the given token volume and tier."""
    t = str(tier).upper()
    rates = BASELINE_PRICING_PER_1M.get(t, BASELINE_PRICING_PER_1M["M"])
    in_cost = (prompt_tokens / 1_000_000.0) * rates[0]
    out_cost = (completion_tokens / 1_000_000.0) * rates[1]
    return round(in_cost + out_cost, 6)


def calculate_savings(
    prompt_tokens: int,
    completion_tokens: int,
    tier: str = "M",
    actual_cost: float = 0.0,
) -> float:
    """Calculates saved USD compared to commercial standard APIs."""
    base = baseline_cost(prompt_tokens, completion_tokens, tier)
    return max(0.0, round(base - actual_cost, 6))

const fs = require('fs');
