  url: "http://127.0.0.1:8080/chat",
  runScripts: "outside-only",
});

dom.window.fetch = async (url, options) => {
  console.log("Mock fetch called:", url);
  return {
    ok: true,
    json: async () => ({}),
    body: {
      getReader: () => {
        let done = false;
        return {
          read: async () => {
            if (done) return { done: true };
            done = true;
            return { value: Buffer.from("data: [DONE]\n\n"), done: false };
          }
