  };
}

function stopGeneration() {
  if (abortController) {
    abortController.abort();
    abortController = null;
  }
  setGenerating(false);
}

function setGenerating(gen) {
  isGenerating = gen;
  if (gen) {
    btnSend.textContent = '■';
    btnSend.title = 'Stop generating';
  } else {
    btnSend.textContent = '↑';
    btnSend.title = 'Send message';
  }
}

async function sendMessage() {
  const text = chatInput.value.trim();
  if (!text || isGenerating) return;

  chatInput.value = '';
  chatInput.style.height = 'auto';

  appendUserMessage(text);
  history.push({ role: 'user', content: text });

  const isStream = optStream ? optStream.checked : true;
  const isThinking = optThinking ? optThinking.checked : false;
  const model = (modelSelect && modelSelect.value) ? modelSelect.value : 'auto';
  const privacy = (optPrivacy && optPrivacy.value) ? optPrivacy.value : 'default';

  const cleanMessages = history.filter(m => m && m.content && String(m.content).trim().length > 0);

  const payload = {
    model: model,
    messages: cleanMessages,
    stream: isStream,
    enable_thinking: isThinking,
    privacy: privacy,
  };

  const assistantMsg = createAssistantMessage();
  let fullContent = '';
  let routerMeta = null;

  setGenerating(true);
  abortController = new AbortController();

  try {
    const response = await fetch('/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': isStream ? 'text/event-stream, application/json' : 'application/json'
      },
      body: JSON.stringify(payload),
      signal: abortController.signal
    });

    if (!response.ok) {
      const errJson = await response.json().catch(() => ({}));
      const errMsg = (errJson.error && errJson.error.message) ? errJson.error.message : response.statusText;
      assistantMsg.contentEl.innerHTML = '<span style="color:var(--red);background:var(--red-bg);padding:8px 12px;border-radius:6px;display:inline-block">Error: ' + escapeHtml(errMsg) + '</span>';
      setGenerating(false);
      return;
    }

    if (isStream) {
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed.startsWith('data:')) continue;
          const dataStr = trimmed.slice(5).trim();
          if (dataStr === '[DONE]') break;
          try {
            const chunk = JSON.parse(dataStr);
            if (chunk.error) {
              const errMsg = typeof chunk.error === 'string' ? chunk.error : (chunk.error.message || JSON.stringify(chunk.error));
              assistantMsg.contentEl.innerHTML = '<span style="color:var(--red);background:var(--red-bg);padding:8px 12px;border-radius:6px;display:inline-block">Error: ' + escapeHtml(errMsg) + '</span>';
              return;
            }
            const c0 = (chunk.choices && chunk.choices[0]) || {};
            const d = c0.delta || {};
            const delta = extractText(d) || (typeof d.content === 'string' ? d.content : '');
            if (delta) {
              fullContent += delta;
              assistantMsg.contentEl.innerHTML = renderMarkdown(fullContent) + '<span class="cursor-blink"></span>';
              messagesContainer.scrollTop = messagesContainer.scrollHeight;
            }
            if (chunk.router) {
              routerMeta = chunk.router;
            }
          } catch (e) {}
        }
      }
      if (!fullContent) {
        assistantMsg.contentEl.innerHTML = '<span style="color:var(--text-muted)">(Empty response from model)</span>';
      } else {
        assistantMsg.contentEl.innerHTML = renderMarkdown(fullContent);
      }
    } else {
      const data = await response.json();
      if (data.error) {
        const errMsg = typeof data.error === 'string' ? data.error : (data.error.message || JSON.stringify(data.error));
        assistantMsg.contentEl.innerHTML = '<span style="color:var(--red);background:var(--red-bg);padding:8px 12px;border-radius:6px;display:inline-block">Error: ' + escapeHtml(errMsg) + '</span>';
        setGenerating(false);
        return;
      }
      const m0 = (data.choices && data.choices[0] && data.choices[0].message) || {};
      fullContent = extractText(m0) || (typeof m0.content === 'string' ? m0.content : '');
      routerMeta = data.router;
      if (!fullContent) {
        assistantMsg.contentEl.innerHTML = '<span style="color:var(--text-muted)">(Empty response from model)</span>';
      } else {
        assistantMsg.contentEl.innerHTML = renderMarkdown(fullContent);
      }
    }

    if (fullContent && fullContent.trim()) {
      history.push({ role: 'assistant', content: fullContent });
    }

    if (routerMeta) {
      const prov = routerMeta.provider || '—';
      const mName = routerMeta.model || '—';
      const tier = routerMeta.complexity_tier || '—';
      const lat = routerMeta.latency_ms ? routerMeta.latency_ms + 'ms' : '';
      const cached = routerMeta.cache === 'hit' ? 'cached' : 'fresh';
      assistantMsg.metaEl.innerHTML = `
        <div class="router-pill">
          <span>⚡ <b>Router:</b> ${escapeHtml(prov)} · ${escapeHtml(mName)} · Tier ${escapeHtml(tier)} ${lat ? '· ' + lat : ''} · ${cached}</span>
        </div>
      `;
    }
  } catch (err) {
    if (err.name !== 'AbortError') {
      assistantMsg.contentEl.innerHTML = '<span style="color:var(--red);background:var(--red-bg);padding:8px 12px;border-radius:6px;display:inline-block">Connection error: ' + escapeHtml(err.message) + '</span>';
    } else {
      assistantMsg.contentEl.innerHTML = renderMarkdown(fullContent) + ' <span style="color:var(--text-muted);font-size:12px">(stopped)</span>';
    }
  } finally {
    setGenerating(false);
    abortController = null;
    messagesContainer.scrollTop = messagesContainer.scrollHeight;
  }
}

"""End-to-end checks of new features via the HTTP facade: PII → strict, cascade."""
import os
import tempfile
from contextlib import contextmanager

import httpx
from fastapi.testclient import TestClient

MANIFEST = """
providers:
  - name: cheap
    base_url: http://a:1/v1
    trains_on_data: true
    free: true
    limits: { rpm: 60, rpd: 100 }
    models:
      - id: small
        tier: S
        ctx_window: 32768
        caps: [json, stream]
        quality_score: 0.9
        ttft_p50_ms: 50
  - name: good
    base_url: http://b:2/v1
    trains_on_data: true
    free: true
    limits: { rpm: 60, rpd: 100 }
    models:
      - id: big
        tier: L
        ctx_window: 32768
        caps: [json, stream]
        quality_score: 0.9
        ttft_p50_ms: 200
  - name: local
    base_url: http://c:3/v1
    is_local: true
    trains_on_data: false
    free: true
    models:
      - id: qwen
        tier: L
        ctx_window: 32768
        caps: [json, stream]
        quality_score: 0.5
"""


@contextmanager
def _make_client(monkeypatch, handler):
    tmp = tempfile.TemporaryDirectory()
    manifest = os.path.join(tmp.name, "providers.yaml")
    with open(manifest, "w") as f:
        f.write(MANIFEST)
    monkeypatch.setenv("ROUTER_MANIFEST_PATH", manifest)
    monkeypatch.setenv("ROUTER_DB_PATH", os.path.join(tmp.name, "r.db"))
    monkeypatch.setenv("ROUTER_ENABLE_DISCOVERY", "false")

    import waypost.server as srv

    srv.settings = srv.Settings()
    original = httpx.AsyncClient

    def with_local_discovery(request: httpx.Request) -> httpx.Response:
        if request.method == "GET" and request.url.path.endswith("/models"):
            return httpx.Response(200, json={"data": [{"id": "qwen"}]})
        return handler(request)

    def patched(*args, **kwargs):
        kwargs["transport"] = httpx.MockTransport(with_local_discovery)
        return original(*args, **kwargs)

    monkeypatch.setattr(httpx, "AsyncClient", patched)
    with TestClient(srv.app) as c:
        yield c
    tmp.cleanup()


def test_pii_forces_strict_without_explicit_flag(monkeypatch):
    calls = []

    def handler(request: httpx.Request) -> httpx.Response:
        calls.append(f"{request.url.host}:{request.url.port}")
        return httpx.Response(
            200,
            json={
                "id": "x",
                "model": "m",
                "choices": [
                    {
                        "index": 0,
                        "finish_reason": "stop",
                        "message": {"role": "assistant", "content": "ok"},
                    }
                ],
                "usage": {
                    "prompt_tokens": 5,
                    "completion_tokens": 2,
                    "total_tokens": 7,
                },
            },
        )

    with _make_client(monkeypatch, handler) as c:
        r = c.post(
            "/v1/chat/completions",
            json={
                "model": "auto",
                "messages": [{"role": "user", "content": "мой email a.b@example.com"}],
            },
        ).json()
    # PII found → privacy strict → local model only
    assert r["router"]["provider"] == "local"
    assert calls == ["c:3"]


def test_cascade_escalates_on_bad_cheap_response(monkeypatch):
    def handler(request: httpx.Request) -> httpx.Response:
        host = f"{request.url.host}:{request.url.port}"
        if host == "a:1":  # cheap model — empty answer
            content, finish = "", "stop"
        else:  # expensive — normal
            content, finish = "42", "stop"
        return httpx.Response(
            200,
            json={
                "id": "x",
                "model": "m",
                "choices": [
                    {
                        "index": 0,
                        "finish_reason": finish,
                        "message": {"role": "assistant", "content": content},
                    }
                ],
                "usage": {
                    "prompt_tokens": 5,
                    "completion_tokens": 2,
                    "total_tokens": 7,
                },
            },
        )

    with _make_client(monkeypatch, handler) as c:
        r = c.post(
            "/v1/chat/completions",
            json={
                "model": "auto",
                "messages": [{"role": "user", "content": "извлеки число"}],
            },
        ).json()
    # Empty answer from the cheap model → escalation to a higher tier
    assert r["choices"][0]["message"]["content"] == "42"
    assert r["router"]["provider"] == "good"


def test_cascade_falls_back_when_upstream_returns_no_choices(monkeypatch):
    def handler(request: httpx.Request) -> httpx.Response:
